  [{ zh: '零售服务小程序', en: 'Retail Service Mini Program' }, { zh: '连接门店、商品与服务，让每一次使用都更轻。', en: 'Connecting stores, products and service in a lighter daily experience.' }, 'mini', ['MINI', 'UX']],
